-- Seed for the `vars` Go⇄Rust compatibility tests (applied on top of the
-- DevStats schema, `structure/full_structure.sql`).
--
-- `sprojects_health` is the TSDB table of the "Projects health" metric that
-- `metrics/*/sync_vars.yaml` reads with its `queries:` (`select series, name,
-- str from sprojects_health where period = 'd' and series like 'phealth%'`).
-- Its shape is the one `WriteTSPoints` creates for `s<series>` tables; the
-- rows of 12 series are real (devstats.cncf.io `allprj`, 2026-09-10) and every
-- other series referenced by `partials/projects_health*.html` gets synthetic
-- rows so that the whole template is expanded (plus rows of other periods
-- and series that the query must not pick up).

create table sprojects_health (
  time timestamp without time zone not null,
  series text not null,
  period text not null default '',
  name text not null default '',
  value double precision not null default 0.0,
  str text not null default '',
  dt timestamp without time zone not null default '1900-01-01 00:00:00',
  primary key (time, series, period)
);
create index iprojects_healthp on sprojects_health using btree (period);
create index iprojects_healths on sprojects_health using btree (series);
create index iprojects_healtht on sprojects_health using btree (time);


-- synthetic rows for the remaining series of the templates: the 76 metric
-- names of the real rows, `str` = 'test <series> <n>'
select
  timestamp '2012-07-01 00:00:00' + n.i * interval '1 hour',
  s.series,
  'd',
  n.name,
  n.i,
  'test ' || s.series || ' ' || n.i,
  timestamp '2026-01-01 00:00:00'
