-- rows the `sync_vars.yaml` query must ignore (other period / other series)

-- a small table for the test project's `queries:` (NULLs, duplicates of the
-- key column, unicode, empty strings, non-text columns)
create table vars_test_data (
  id int primary key,
  grp text,
  label text,
  amount numeric(10, 2),
  ts timestamp,
  flag boolean
);

-- pre-existing variables: the run must update `value_<type>` in place and
-- leave the other columns and other rows alone
